// === Tab: mySketch ===
let numParticles = 50;

let particlePos = [];
let particleVel = [];

let centerAttractMult = 2;
let airResistance = 0.99;
let dAttract = 0.005;

let lenDiv = 282.8;
let lineBias = 1;
let linePow = 1.3;

let multTimes = 0;

let xRot = 0;
let yRot = 0;
let xRotMult = 0.01;
let yRotMult = 0.01;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);

	reset();
	strokeWeight(3);
	colorMode(HSB);
}

function draw() {
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
		xRot -= ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) * xRotMult;
		yRot -= ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) * yRotMult;
	}
	// translate(-width/2, -height/2);
	rotateX(yRot);
	rotateZ(xRot);
	background(0);

	strokeWeight(1);
	colorMode(RGB);
	stroke(255, 0, 0);
	line(-width, 0, 0, width, 0, 0);
	stroke(0, 255, 0);
	line(0, -width, 0, 0, width, 0);
	stroke(0, 0, 255);
	line(0, 0, -width, 0, 0, width);
	strokeWeight(3);
	colorMode(HSB);

	centerAttractMult -= dAttract;
	if (centerAttractMult < -0.2 || centerAttractMult > 4) {
		dAttract *= -1;
		if (centerAttractMult > 4) {
			dAttract *= 5;
			multTimes++;

			if (multTimes == 5) {
				strokeWeight(6);
				background(255);
			}
		}
	}
	for (let i = 0; i < numParticles; i++) {
		for (let j = 0; j < numParticles; j++) {
			if (j != i) {
				// particleVel[i].add(attract(j, particlePos[i].x, particlePos[i].y));
				let gravAttract = attract(j, particlePos[i].x, particlePos[i].y);
				let newAttract = createVector(-gravAttract.y, gravAttract.x + gravAttract.y);
				particleVel[i].add(newAttract);

			}
		}
		particleVel[i].add(centerAttract(particlePos[i].x, particlePos[i].y).mult(centerAttractMult));

		particlePos[i].add(particleVel[i]);
		particleVel[i].mult(airResistance);

		stroke((frameCount + (i / numParticles) * 50) % 255, 255, 255);
		let lineLength = pow(dist(particlePos[i].x, particlePos[i].y, 0, 0), linePow) / lenDiv + lineBias;
		line(particlePos[i].x, particlePos[i].y, particlePos[i].x - particleVel[i].x * lineLength, particlePos[i].y - particleVel[i].y * lineLength);
	}
}

function attract(attractIndex, posX, posY) {
	let attractionForce = createVector(posX - particlePos[attractIndex].x, posY - particlePos[attractIndex].y);
	attractionForce.normalize();

	let amp = 1 / sqrt(dist(posX, posY, particlePos[attractIndex].x, particlePos[attractIndex].y));
	amp /= numParticles
	attractionForce.mult(-2 * amp);

	return attractionForce;
}

function centerAttract(posX, posY) {
	var attractionForce = createVector(posX, posY);
	attractionForce.normalize();
	var amp = 1 / sqrt(dist(posX, posY, 0, 0));
	attractionForce.mult(-4 * amp);
	return attractionForce;
}

function reset() {
	background(0);

	for (let i = 0; i < numParticles; i++) {
		particlePos[i] = createVector(random(-width / 2, width / 2), random(-height / 2, height / 2));
		particleVel[i] = createVector(0, 0);
	}
}

function keyPressed() {
	if (keyCode == LEFT_ARROW) numParticles -= ceil(sqrt(numParticles));
	if (keyCode == RIGHT_ARROW) numParticles += ceil(sqrt(numParticles));

	numParticles = constrain(numParticles, 1, 1000);
	reset();
}

